/* Careers photo strip: AI-generated faces with fictional "First L." names.
   No real staff appear here. */
(function () {
  var root = document.getElementById('cj-faces');
  if (!root) return;
  var pool = [
    { photo: 'data:image/webp;base64,', label: 'Daniel K.' },
    { photo: 'data:image/webp;base64,', label: 'Heather J.' },
    { photo: 'data:image/webp;base64,', label: 'Naomi W.' },
    { photo: 'data:image/webp;base64,', label: 'Marcus O.' },
    { photo: 'data:image/webp;base64,', label: 'Grace L.' },
    { photo: 'data:image/webp;base64,', label: 'Leila H.' }
  ];
  var slots = [].slice.call(root.querySelectorAll('.cjf-slot'));
  var shown = [];
  function paint(slot, item, layer) {
    var img = slot.querySelectorAll('img')[layer];
    img.src = item.photo;
    img.alt = item.label ? item.label : '';
    slot.querySelector('figcaption').textContent = item.label || '\u00a0';
    slot.classList.toggle('named', !!item.label);
  }
  slots.forEach(function (s, i) {
    var item = pool[i % pool.length]; shown[i] = i % pool.length;
    paint(s, item, 0); s.dataset.layer = '0';
  });
  var reduce = window.matchMedia && matchMedia('(prefers-reduced-motion: reduce)').matches;
  if (reduce || pool.length <= slots.length) return;
  var next = slots.length % pool.length, turn = 0, paused = false, resumeT;
  function visibleSlots() { return slots.filter(function (s) { return s.offsetParent !== null; }); }
  function tick() {
    if (paused || document.hidden) return;
    var vis = visibleSlots(); if (!vis.length) return;
    var s = vis[turn++ % vis.length], idx = slots.indexOf(s);
    var onScreen = vis.map(function (v) { return shown[slots.indexOf(v)]; });
    var guard = 0;
    while (onScreen.indexOf(next) !== -1 && guard++ < pool.length) next = (next + 1) % pool.length;
    var item = pool[next]; shown[idx] = next; next = (next + 1) % pool.length;
    var cur = +s.dataset.layer, nl = 1 - cur, img = s.querySelectorAll('img')[nl];
    var go = function () {
      s.dataset.layer = String(nl);
      img.classList.add('on'); s.querySelectorAll('img')[cur].classList.remove('on');
      var cap = s.querySelector('figcaption'); cap.textContent = item.label || '\u00a0';
      s.classList.toggle('named', !!item.label);
    };
    img.onload = go; img.src = item.photo;
    img.alt = item.label ? item.label : '';
    if (img.complete && img.naturalWidth) { img.onload = null; go(); }
  }
  setInterval(tick, 2600);
  function pause() { paused = true; clearTimeout(resumeT); }
  function resume(ms) { clearTimeout(resumeT); resumeT = setTimeout(function () { paused = false; }, ms || 0); }
  root.addEventListener('mouseenter', pause);
  root.addEventListener('mouseleave', function () { resume(400); });
  root.addEventListener('focusin', pause);
  root.addEventListener('focusout', function () { resume(400); });
  root.addEventListener('touchstart', pause, { passive: true });
  root.addEventListener('touchend', function () { resume(5000); }, { passive: true });
})();
